def render_tariff_cards(cards):
    """Карточка с двойной рамкой (teal+yellow) и парой круглых фото —
    общий компонент для «Варианты аренды залов» и «Праздники под ключ».
    note/price необязательны — у карточки «Корпоратив» их нет в оригинале."""
    out = []
    for n, t in enumerate(cards):
        note = '<p class="tariff__note">%s</p>' % t['note'] if t['note'] else ''
        price = '<p class="tariff__price">%s</p>' % t['price'] if t['price'] else ''
        out.append(
            '<article class="tariff" style="background:%s" data-anim="zoomin" data-anim-dur="1" data-anim-delay="%.1f">'
            '<span class="tariff__frame tariff__frame--teal"><img src="%stild3031-6236-4236-a561-356461643236__e19497dc-0442-4f7b-b.svg" alt=""></span>'
            '<span class="tariff__frame tariff__frame--yellow"><img src="%stild3934-3735-4063-b837-356461626263__04c0fbd0-c82b-48fb-a.svg" alt=""></span>'
            '<span class="tariff__photo tariff__photo--big"><img src="%s%s" alt="" width="196" height="196"></span>'
            '<span class="tariff__photo tariff__photo--small"><img src="%s%s" alt="" width="162" height="162"></span>'
            '<h3 class="tariff__title">%s</h3>'
            '<p class="tariff__desc">%s</p>'
            '%s%s'
            '<a class="tariff__more" href="%s">Подробнее'
            '<img src="%stild6461-6262-4664-a333-343239356263__arrow_7.svg" alt="" width="20" height="11"></a>'
            '</article>'
            % (t['color'], n * 0.1, IMG, IMG, IMG, t['big'], IMG, t['small'], t['title'], t['desc'],
               note, price, t['href'], IMG))
    return ''.join(out)


def text_to_html(text):
    """Пустая строка внутри текста — абзац, одиночный перенос — <br>."""
    paras = text.split('\n\n')
    return ''.join('<p>%s</p>' % escape(p).replace('\n', '<br>') for p in paras if p.strip())


def render_popups(popups):
    """Поп-ап карточки-программы: заголовок, подзаголовок, текст, галерея.
    Открывается по клику на ссылку href="#popup:KEY" (см. скрипт внизу
    страницы), <dialog> даёт фокус-ловушку и закрытие по Esc бесплатно."""
    out = []
    for key, p in popups.items():
        gallery = ''.join(
            '<img src="%s%s" alt="" loading="lazy" width="260" height="195">' % (IMG, img)
            for img in p['images'])
        out.append(
            '<dialog class="popup" id="popup-%s" aria-label="%s">'
            '<div class="popup__box">'
            '<button class="popup__close" type="button" data-popup-close>Назад</button>'
            '<h3 class="popup__title">%s</h3>'
            '<div class="popup__subtitle">%s</div>'
            '<div class="popup__text">%s</div>'
            '<div class="popup__gallery">%s</div>'
            '</div>'
            '</dialog>'
            % (key, escape(p['title']), escape(p['title']), text_to_html(p['subtitle']),
               text_to_html(p['body']), gallery))
    return ''.join(out)


def render_form_popup(popup_id):
    """Форма заявки (rec591053045 — шапка, rec591047986 — первый экран).
    В оригинале только Имя + Телефон; чекбокс согласия на обработку
    персональных данных в форме добавлен по группе B аудита — его
    в экспорте не было, но без него нельзя принимать заявки законно.
    Отправки без сервера нет: форма показывает подтверждение на месте.
    Заказчик решил (17.08.2026): заявки идут в CRM на два аккаунта-
    администратора Telegram-бота; интеграцию заказчик готовит на стороне
    бота и пришлёт вебхук/API отдельно — подключим, когда будут детали."""
    return (
        '<dialog class="popup popup--form" id="popup-%s" aria-label="Оставьте свои контакты">'
        '<div class="popup__box">'
        '<button class="popup__close" type="button" data-popup-close>Назад</button>'
        '<h3 class="popup__title">Оставьте свои контакты</h3>'
        '<div class="popup__subtitle"><p>И мы свяжемся с Вами в ближайшее время!</p></div>'
        '<form class="form" data-form>'
        '<label class="form__field"><span class="form__label">Ваше имя</span>'
        '<input class="form__input" type="text" name="name" autocomplete="name" required></label>'
        '<label class="form__field"><span class="form__label">Номер телефона</span>'
        '<input class="form__input" type="tel" name="phone" autocomplete="tel" required></label>'
        '<label class="form__consent"><input type="checkbox" name="consent" required>'
        '<span>Согласен(-на) на <a href="/privacy.html" target="_blank">обработку персональных данных</a></span></label>'
        '<button class="btn btn--yellow form__submit" type="submit">Отправить</button>'
        '</form>'
        '<p class="form__thanks" data-form-thanks hidden>Спасибо! Мы свяжемся с вами в ближайшее время.</p>'
        '</div>'
        '</dialog>'
        % popup_id)


def render_cookie_banner():
    """Баннер согласия на cookie (группа B аудита) — в оригинале его не было
    вообще, добавлен в фирменном стиле подвала (тёмный фон --ink). Показ/
    скрытие и запоминание согласия — на чистом JS, без библиотек cookie-consent."""
    return (
        '<div class="cookie" id="cookie-banner" hidden>'
        '<div class="cookie__box">'
        '<p class="cookie__text">Мы используем файлы cookie, чтобы сайт работал корректно. '
        'Продолжая пользоваться сайтом, вы соглашаетесь с '
        '<a href="/privacy.html">политикой конфиденциальности</a>.</p>'
        '<button class="btn btn--yellow cookie__accept" type="button" id="cookie-accept">Хорошо</button>'
        '</div>'
        '</div>'
    )


def render_mobile_menu():
    items = []
    for label, href, sub in MOBILE_MENU:
        if sub:
            sub_html = ''.join('<li><a class="mobile-menu__sublink" href="%s">%s</a></li>' % (h, t) for t, h in sub)
            items.append(
                '<li><details class="mobile-menu__group"><summary>%s</summary>'
                '<ul class="mobile-menu__sublist">%s</ul></details></li>' % (label, sub_html))
        else:
            items.append('<li><a class="mobile-menu__link" href="%s">%s</a></li>' % (href, label))
    return ''.join(items)


def render_mobile_socials():
    return ''.join(
        '<a class="contact__social" href="%s" target="_blank" rel="nofollow" aria-label="%s">'
        '<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">%s</svg></a>'
        % (url, name, svg) for name, url, svg in SOCIALS)


def render_top_chrome():
    """Баннер cookie + шапка + мобильное меню — одинаковы на всех страницах
    сайта. Кнопка шапки всегда открывает попап #popup:header — его должна
    сгенерировать сама страница через render_form_popup('header')."""
    nav = ''.join('<li><a class="nav__link" href="%s">%s</a></li>' % (h, t) for t, h in NAV)
    return (
        render_cookie_banner() + '\n\n' +
        '<header class="header" id="header">'
        '<div class="stage header__inner">'
        '<a class="header__logo" href="/" aria-label="Порхай — на главную">'
        '<img src="%stild3166-3639-4666-b462-333535343563__photo.svg" alt="Порхай" width="150" height="46"></a>'
        '<nav class="nav" aria-label="Основная навигация"><ul class="nav__list">%s</ul></nav>'
        '<a class="btn btn--teal header__cta" href="#popup:header">Забронировать зал</a>'
        '<button class="burger" type="button" aria-label="Меню" aria-expanded="false" aria-controls="mobile-menu">'
        '<span></span><span></span><span></span></button>'
        '</div></header>\n\n'
        '<div class="mobile-menu" id="mobile-menu" hidden>'
        '<div class="mobile-menu__inner">'
        '<button class="mobile-menu__close" type="button" aria-label="Закрыть меню"><span></span><span></span></button>'
        '<ul class="mobile-menu__list">%s</ul>'
        '<div class="mobile-menu__socials">%s</div>'
        '<p class="mobile-menu__copy">© Развлекательный центр «Порхай»</p>'
        '</div></div>'
        % (IMG, nav, render_mobile_menu(), render_mobile_socials())
    )


def render_faq_section(faq=None, title='Отвечаем на ваши вопросы'):
    """FAQ-аккордеон на <details>, без JS. Один и тот же список вопросов
    (rec567879748 и аналоги) переиспользуется почти на всех страницах."""
    faq = FAQ if faq is None else faq
    items = ''.join(
        '<details class="faq__item"%s>'
        '<summary class="faq__q">%s<span class="faq__icon" aria-hidden="true"></span></summary>'
        '<div class="faq__a">%s</div>'
        '</details>'
        % (' open' if n == 0 else '', q, a)
        for n, (q, a) in enumerate(faq))
    return (
        '<section class="section section--faq" id="faq">'
        '<div class="stage">'
        '<h2 class="section__title" data-anim="fadeinup" data-anim-dur="1">%s</h2>'
        '<div class="faq">%s</div>'
        '</div></section>' % (title, items)
    )


def faq_jsonld(faq=None):
    faq = FAQ if faq is None else faq
    return json.dumps({
        '@context': 'https://schema.org',
        '@type': 'FAQPage',
        'mainEntity': [{
            '@type': 'Question', 'name': q,
            'acceptedAnswer': {'@type': 'Answer', 'text': a},
        } for q, a in faq],
    }, ensure_ascii=False)


